pub fn longest(strings: Vec<Vec<char>>) -> Option<Vec<char>> {
    // Empty input => no longest sequence
    if strings.is_empty() {
        return None;
    }

    // Track the best index seen so far; keep the earliest on ties.
    let mut best_idx: usize = 0;
    let mut best_len: usize = strings[0].len();

    for (i, s) in strings.iter().enumerate().skip(1) {
        let len = s.len();
        if len > best_len {
            best_len = len;
            best_idx = i;
        }
        // If len == best_len, do nothing to preserve earliest index.
    }

    // Return an owned sequence equal in content to an input element.
    Some(strings[best_idx].clone())
}